Given an array arr[] of size n, the task is to divide it into two sets s1 and s2 such that the absolute difference between their sums is minimum. Example: Input: arr = [1, 6, 11, 5]Output: 1Explanation: S1 = [1, 5, 6], sum = 12,  S2 = [11], sum = 11,  Absolute Difference (12 - 11) = 1Input: arr = [1, 5, 11, 5]Output: 0Explanation: S1 = [1, 5, 5], sum = 11, S2 = [11], sum = 11, Absolute Difference (11 - 11) = 0 Try It YourselfTable of ContentUsing Recursion - O(2^n) Time and O(n) SpaceUsing Top-Down DP (Memoization) - O(n*sumTotal) Time and O(n*sumTotal) SpaceUsing Bottom-Up DP (Tabulation) - O(n*sumTotal) Time and O(n*sumTotal) SpaceUsing Space Optimized DP - O(n*sumTotal) Time and O(sumTotal) SpaceUsing Recursion - O(2^n) Time and O(n) SpaceFor the recursive approach, there will be two cases:Include the last element in the subset: The new sumCalculated becomes sumCalculated + arr[n-1].Exclude the last element: Keep sumCalculated unchanged.Mathematically, the recurrence relation is:minDiff(arr, n, sumCalculated) = min(minDiff(arr, n-1, sumCalculated), minDiff(arr, n-1, sumCalculated + arr[n-1])).Base Cases:If n = 0: Return the absolute difference |(sumTotal - sumCalculated) - sumCalculated|.
            C++

    // C++ Code to partition a set into two 
// subsets such that the difference 
// of subset sums is minimum
#include <bits/stdc++.h>
using namespace std;

// Function to calculate the minimum absolute difference
int minDiff(vector<int>& arr, int n, 
                      int sumCalculated, int sumTotal) {

    // Base case: if we've considered all elements
    if (n == 0) {
        return abs((sumTotal - sumCalculated) 
                                    - sumCalculated);
    }

    // Include the current element in the subset
    int include = minDiff(arr, n - 1, 
                    sumCalculated + arr[n - 1], sumTotal);

    // Exclude the current element from the subset
    int exclude = minDiff(arr,
                       n - 1, sumCalculated, sumTotal);

    // Return the minimum of both choices
    return min(include, exclude);
}

// Function to get the minimum difference
int minDifference(vector<int>& arr) {
    int sumTotal = 0;

    // Calculate total sum of the array
    for (int num : arr) {
        sumTotal += num;
    }

    // Call recursive function to find 
    // the minimum difference
    return minDiff(arr, 
                       arr.size(), 0, sumTotal);
}

int main() {

    vector<int> arr = {1, 6, 11, 5};

    cout << minDifference(arr) << endl;

    return 0;
}


